import { test, expect } from '@playwright/test';

test.describe('Checkout Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
  });

  test('Complete checkout process', async ({ page }) => {
    await page.click('[data-test="add-to-cart-sauce-labs-backpack"]');
    await page.click('.shopping_cart_link');
    await page.click('[data-test="checkout"]');

    await page.fill('[data-test="firstName"]', 'Saif');
    await page.fill('[data-test="lastName"]', 'Afzal');
    await page.fill('[data-test="postalCode"]', '201301');
    await page.click('[data-test="continue"]');

    const itemTotal = await page.locator('.summary_subtotal_label').textContent();
    expect(itemTotal).toContain('Item total:');
  });

  test('Confirm order completion', async ({ page }) => {
    await page.click('[data-test="finish"]');
    const confirmationHeader = await page.locator('.complete-header').textContent();
    expect(confirmationHeader).toBe('Thank you for your order!');
  });
});
